# ---- sprout_db.py ----

import os
from datetime import date, datetime, time, timezone

import requests

HOST = os.getenv("SPACETIMEDB_HOST", "https://maincloud.spacetimedb.com").rstrip("/")
DB = os.getenv("SPACETIMEDB_DB", "sprout-live")
TIMEOUT = 20


class DbError(RuntimeError):
    """A reducer rejected the call or the database couldn't be reached."""


def enabled() -> bool:
    return bool(os.getenv("SPACETIMEDB_TOKEN"))


def _headers() -> dict:
    return {"Authorization": f"Bearer {os.environ['SPACETIMEDB_TOKEN']}"}


# ---- argument encoding (SpacetimeDB's JSON format) ----

def some(value):
    return {"some": value}


NONE = {"none": []}


def opt(value):
    """Option argument: {"some": v} or {"none": []}."""
    return NONE if value is None or value == "" else some(value)


def timestamp(value):
    """A date, datetime or YYYY-MM-DD string as a SpacetimeDB timestamp (UTC midnight for dates)."""
    if isinstance(value, str):
        value = date.fromisoformat(value)
    if isinstance(value, date) and not isinstance(value, datetime):
        value = datetime.combine(value, time(0), tzinfo=timezone.utc)
    micros = int(value.timestamp() * 1_000_000)
    return {"__timestamp_micros_since_unix_epoch__": micros}


# ---- calls ----

def call(reducer: str, *args):
    try:
        r = requests.post(f"{HOST}/v1/database/{DB}/call/{reducer}", json=list(args),
                          headers=_headers(), timeout=TIMEOUT)
    except requests.RequestException as err:
        raise DbError(f"{reducer}: {err}") from err
    if not r.ok:
        raise DbError(f"{reducer}: {r.text.strip()[:300]}")


def _decode(value):
    """SQL results return options as [0, value] (some) or [1, []] (none)."""
    if isinstance(value, list) and len(value) == 2 and value[0] in (0, 1) and (value[0] == 0 or value[1] == []):
        return value[1] if value[0] == 0 else None
    return value


def sql(query: str) -> list:
    try:
        r = requests.post(f"{HOST}/v1/database/{DB}/sql", data=query, headers=_headers(), timeout=TIMEOUT)
    except requests.RequestException as err:
        raise DbError(f"sql: {err}") from err
    if not r.ok:
        raise DbError(f"sql: {r.text.strip()[:300]}")
    result = r.json()[0]
    names = [e["name"]["some"] for e in result["schema"]["elements"]]
    return [dict(zip(names, (_decode(v) for v in row))) for row in result["rows"]]


def sql_str(text: str) -> str:
    """A SQL string literal."""
    return "'" + str(text).replace("'", "''") + "'"


# ---- relay.py ----

import os
from datetime import datetime, timezone
from uuid import uuid4

from uagents import Context, Model, Protocol
from uagents_core.contrib.protocols.chat import ChatMessage, StartSessionContent, TextContent


class StudentTurn(Model):
    user: str             # the student's ASI:One address
    text: str = ""        # what they typed, or a card's selection JSON
    start: bool = False   # a brand-new chat


class StudentReplies(Model):
    user: str
    messages: list[str]   # ChatMessage JSON, in the order they were sent


def turn_message(turn: StudentTurn) -> ChatMessage:
    content = [StartSessionContent(type="start-session")] if turn.start else []
    if turn.text:
        content.append(TextContent(type="text", text=turn.text))
    return ChatMessage(timestamp=datetime.now(timezone.utc), msg_id=uuid4(), content=content)


def fresh(raw: str) -> ChatMessage:
    """A relayed message with its own id and time, as the orchestrator's message to the student."""
    msg = ChatMessage.model_validate_json(raw)
    return ChatMessage(timestamp=datetime.now(timezone.utc), msg_id=uuid4(), content=msg.content)


def trusted() -> set:
    return {a.strip() for a in os.getenv("TRUSTED_ORCHESTRATORS", "").split(",") if a.strip()}


class CaptureContext:
    """Stands in for the handler's Context: messages to the student are collected instead of sent.

    Storage, logging and messages to anyone else go through the real context.
    """

    def __init__(self, ctx: Context, user: str):
        self._ctx, self._user, self.messages = ctx, user, []

    def __getattr__(self, name):
        return getattr(self._ctx, name)

    async def send(self, destination: str, message, *args, **kwargs):
        if destination == self._user:
            if isinstance(message, ChatMessage):
                self.messages.append(message.model_dump_json())
            return None  # acknowledgements to the student are the orchestrator's job
        return await self._ctx.send(destination, message, *args, **kwargs)


async def handle_turn(ctx: Context, sender: str, turn: StudentTurn, on_chat):
    """Runs the specialist's chat handler as the student and replies with what it would have sent."""
    if sender not in trusted():
        ctx.logger.warning(f"ignored a relayed turn from untrusted {sender[:20]}")
        return
    capture = CaptureContext(ctx, turn.user)
    await on_chat(capture, turn.user, turn_message(turn))
    await ctx.send(sender, StudentReplies(user=turn.user, messages=capture.messages))


def relay_protocol(on_chat) -> Protocol:
    """Specialist side: runs `on_chat(ctx, user, ChatMessage)` for each trusted StudentTurn."""
    proto = Protocol(name="SproutRelay", version="0.1.0")

    @proto.on_message(model=StudentTurn, replies=StudentReplies)
    async def on_turn(ctx: Context, sender: str, turn: StudentTurn):
        await handle_turn(ctx, sender, turn, on_chat)

    return proto


# ---- concept_map.py ----


import json
import re
from collections import defaultdict

DEFAULT_CONFIDENCE = 0.7
KINDS = {"concept", "skill", "fact"}


def slugify(text: str) -> str:
    slug = re.sub(r"[^a-z0-9]+", "-", str(text).lower()).strip("-")
    return slug or "item"


def extract_json(text: str) -> dict:
    """Pull the first JSON object out of a model reply (handles ``` fences and chatter)."""
    fenced = re.search(r"```(?:json)?\s*(\{.*?\})\s*```", text, re.DOTALL)
    candidate = fenced.group(1) if fenced else text[text.find("{"): text.rfind("}") + 1]
    if not candidate:
        raise ValueError("No JSON object found in model reply")
    return json.loads(candidate)


EXAM_WORDS = re.compile(r"\b(exam|midterm|final|test|quiz)\b", re.I)
DATE_WORDS = re.compile(
    r"\b(jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec)[a-z]*\.?\s+\d{1,2}\b|\b\d{1,2}/\d{1,2}\b|\b\d{4}-\d{2}-\d{2}\b",
    re.I)


def mentions_exam_date(syllabus: str) -> bool:
    return bool(EXAM_WORDS.search(syllabus) and DATE_WORDS.search(syllabus))


def _unique(slug: str, taken: set[str]) -> str:
    out, n = slug, 2
    while out in taken:
        out, n = f"{slug}-{n}", n + 1
    taken.add(out)
    return out


def normalize(raw: dict) -> dict:
    course = raw.get("course") or {}
    if isinstance(course, str):
        course = {"name": course}

    # Units: keep given order, add any a concept refers to but the list missed.
    units, unit_ids, unit_alias = [], set(), {}
    for i, u in enumerate(raw.get("units") or [], start=1):
        if isinstance(u, str):
            u = {"name": u}
        name = str(u.get("name") or u.get("id") or f"Unit {i}").strip()
        uid = _unique(slugify(u.get("id") or name), unit_ids)
        unit_alias[str(u.get("id") or name)] = uid
        unit_alias[name] = uid
        units.append({"id": uid, "name": name, "order": i})

    def unit_for(ref) -> str:
        ref = str(ref or "").strip()
        if ref in unit_alias:
            return unit_alias[ref]
        if slugify(ref) in unit_ids:
            return slugify(ref)
        name = ref or "General"
        uid = _unique(slugify(name), unit_ids)
        unit_alias[ref] = uid
        units.append({"id": uid, "name": name, "order": len(units) + 1})
        return uid

    # Concepts: slug ids, dedupe by id and by name.
    concepts, concept_ids, alias = [], set(), {}
    seen_names: dict[str, str] = {}
    for c in raw.get("concepts") or []:
        if isinstance(c, str):
            c = {"name": c}
        name = str(c.get("name") or c.get("id") or "").strip()
        if not name:
            continue
        key = name.lower()
        if key in seen_names:  # same concept listed twice
            alias[str(c.get("id") or name)] = seen_names[key]
            continue
        cid = _unique(slugify(c.get("id") or name), concept_ids)
        seen_names[key] = cid
        alias[str(c.get("id") or name)] = cid
        alias[name] = cid
        kind = c.get("kind") if c.get("kind") in KINDS else "concept"
        concepts.append({
            "id": cid,
            "name": name,
            "summary": str(c.get("summary") or "").strip(),
            "unit": unit_for(c.get("unit")),
            "kind": kind,
            "source": c.get("source") or None,
        })
    if not concepts:
        raise ValueError("Concept map has no concepts")

    def resolve(ref):
        ref = str(ref or "")
        return alias.get(ref) or (slugify(ref) if slugify(ref) in concept_ids else None)

    # Edges: prerequisite -> dependent. Drop self-loops, dangling refs, duplicates.
    best: dict[tuple[str, str], dict] = {}
    for e in raw.get("edges") or raw.get("prerequisites") or []:
        a, b = resolve(e.get("from")), resolve(e.get("to"))
        if not a or not b or a == b:
            continue
        try:
            conf = float(e.get("confidence", DEFAULT_CONFIDENCE))
        except (TypeError, ValueError):
            conf = DEFAULT_CONFIDENCE
        conf = round(min(1.0, max(0.0, conf)), 2)
        edge = {"from": a, "to": b, "confidence": conf, "reason": e.get("reason") or None}
        if (a, b) not in best or conf > best[(a, b)]["confidence"]:
            best[(a, b)] = edge
    edges = sorted(best.values(), key=lambda e: -e["confidence"])

    # Break cycles: add edges strongest-first, skip any that would close a loop.
    kept, children = [], defaultdict(set)

    def reaches(src: str, dst: str) -> bool:
        stack, seen = [src], set()
        while stack:
            n = stack.pop()
            if n == dst:
                return True
            if n not in seen:
                seen.add(n)
                stack.extend(children[n])
        return False

    for e in edges:
        if reaches(e["to"], e["from"]):
            continue
        children[e["from"]].add(e["to"])
        kept.append(e)

    # Depth = longest prerequisite chain; order = topological, by unit then depth.
    parents = defaultdict(set)
    for e in kept:
        parents[e["to"]].add(e["from"])
    depth: dict[str, int] = {}

    def depth_of(cid: str) -> int:
        if cid not in depth:
            depth[cid] = 1 + max((depth_of(p) for p in parents[cid]), default=-1)
        return depth[cid]

    unit_rank = {u["id"]: u["order"] for u in units}
    position = {c["id"]: i for i, c in enumerate(concepts)}
    for c in concepts:
        c["depth"] = depth_of(c["id"])
    order = [c["id"] for c in sorted(
        concepts, key=lambda c: (c["depth"], unit_rank[c["unit"]], position[c["id"]])
    )]

    used_units = {c["unit"] for c in concepts}
    units = [u for u in units if u["id"] in used_units]
    for i, u in enumerate(units, start=1):
        u["order"] = i

    return {
        "version": 1,
        "course": {
            "name": str(course.get("name") or "Untitled course").strip(),
            "code": course.get("code") or None,
            "exam_date": course.get("exam_date") or None,
        },
        "units": units,
        "concepts": concepts,
        "edges": sorted(kept, key=lambda e: (order.index(e["from"]), order.index(e["to"]))),
        "order": order,
    }


def summarize(cmap: dict) -> str:
    """Short plain-text recap for the chat reply."""
    names = {c["id"]: c["name"] for c in cmap["concepts"]}
    lines = [f"{cmap['course']['name']}: {len(cmap['concepts'])} concepts, "
             f"{len(cmap['edges'])} prerequisite links."]
    for u in cmap["units"]:
        members = [names[cid] for cid in cmap["order"]
                   if next(c for c in cmap["concepts"] if c["id"] == cid)["unit"] == u["id"]]
        lines.append(f"- {u['name']}: {', '.join(members)}")
    return "\n".join(lines)


# ---- prompt.py ----
from datetime import date

SYSTEM_PROMPT = """You turn a course syllabus or notes into a concept map for a study tutor.

Return ONLY one JSON object, no prose, in exactly this shape:
{
  "course": {"name": str, "code": str|null, "exam_date": "YYYY-MM-DD"|null},
  "units": [{"id": "kebab-slug", "name": str}],
  "concepts": [{
    "id": "kebab-slug",
    "name": str,
    "summary": "one sentence a student could check themselves against",
    "unit": "<unit id>",
    "kind": "concept" | "skill" | "fact",
    "source": "short phrase from the syllabus it came from"
  }],
  "edges": [{"from": "<prerequisite concept id>", "to": "<concept that needs it>",
             "confidence": 0.0-1.0, "reason": "few words"}]
}

Rules:
- Concepts are teachable ideas a quiz question could test, not logistics. Skip grading, office hours, dates, readings.
- Aim for 8-30 concepts. Split broad topics ("Trees") into testable pieces ("BST insertion", "Tree traversals").
- kind: concept = idea to understand, skill = procedure to practice, fact = thing to memorize.
- An edge means a student must understand "from" before "to" makes sense. Only add direct prerequisites, not every ancestor.
- Edges may cross units. Add prerequisites the syllabus implies but does not list (e.g. Big-O before comparing sorts), with lower confidence.
- No cycles. Every id in edges must exist in concepts.
- Keep units in syllabus order. If there are no units, group by week or theme.
- exam_date is the next exam on or after today. If the syllabus gives no year, use the first such date on or after today. Use null if no exam date is given.
"""


def user_prompt(syllabus: str, course_name=None) -> str:
    head = f"Today is {date.today().isoformat()}.\n"
    if course_name:
        head += f"Course: {course_name}\n"
    return f"{head}\nSyllabus or notes:\n<<<\n{syllabus.strip()}\n>>>"


